"""Date-window membership for the date_window fixture."""

from __future__ import annotations
import re
from datetime import datetime


def _is_valid_date(date_str: str) -> bool:
    """Check if a date string is valid in YYYY-MM-DD format."""
    pattern = r'^\d{4}-\d{2}-\d{2}$'
    if not re.match(pattern, date_str):
        return False

    try:
        datetime.strptime(date_str, '%Y-%m-%d')
        return True
    except ValueError:
        return False


def _parse_date(date_str: str) -> tuple[int, int, int]:
    """Parse and validate a date string, raising ValueError if invalid."""
    if not _is_valid_date(date_str):
        raise ValueError(f"Invalid date format: {date_str}")

    parts = date_str.split('-')
    return (int(parts[0]), int(parts[1]), int(parts[2]))


def _compare_dates(date1: tuple[int, int, int], date2: tuple[int, int, int]) -> int:
    """Compare two dates. Returns -1 if date1 < date2, 0 if equal, 1 if date1 > date2."""
    if date1 < date2:
        return -1
    elif date1 > date2:
        return 1
    else:
        return 0


def in_any_window(target_date: str, windows: list[tuple[str, str]]) -> bool:
    """Return whether target_date falls inside any date window.

    All dates must be in YYYY-MM-DD format. Windows are inclusive on both
    boundaries. Raises ValueError for malformed dates or invalid windows.
    """
    # Validate and parse target date
    target = _parse_date(target_date)

    # Check each window
    for start_str, end_str in windows:
        # Validate and parse window boundaries
        start = _parse_date(start_str)
        end = _parse_date(end_str)

        # Check if start > end (invalid window)
        if _compare_dates(start, end) > 0:
            raise ValueError(f"Invalid window: start {start_str} is after end {end_str}")

        # Check if target is within this window (inclusive on both ends)
        if _compare_dates(target, start) >= 0 and _compare_dates(target, end) <= 0:
            return True

    return False
